59	// configureFlowDeps contains side effects used by the interactive configure
60	// flow. Tests can replace individual operations without a keyring, browser,
61	// GitHub CLI, or live control plane.
62	type configureFlowDeps struct {
63		resolveAuth  func(context.Context) (statusTarget, error)
64		fetchProfile profileFetcher
65		runLogin     func(context.Context, io.Writer, io.Writer) error
66		accessClient func(context.Context) (configureAccessReporter, error)
67		coreClient   func() (*coreapi.Client, error)
68		openURL      browserOpenFunc
69		githubAdmin  func(context.Context, string, string) (bool, error)
70		now          func() time.Time
71	}
72	
73	func newConfigureFlowDeps(insecure bool) configureFlowDeps {
74		return configureFlowDeps{
75			resolveAuth: func(ctx context.Context) (statusTarget, error) {
76				return resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
77			},
78			fetchProfile: defaultFetchProfile,
79			runLogin: func(ctx context.Context, outW, errW io.Writer) error {
80				cmd := newLoginCmd()
81				cmd.SetContext(ctx)
82				cmd.SetOut(outW)
83				cmd.SetErr(errW)
84				return cmd.RunE(cmd, nil)
85			},
86			accessClient: func(ctx context.Context) (configureAccessReporter, error) {
87				return NewAuthenticatedAPIClient(ctx, insecure)
88			},
89			coreClient:  coreapi.New,
90			openURL:     openBrowser,
91			githubAdmin: configureGitHubAdmin,
92			now:         time.Now,
93		}
94	}
