274	func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
275		raw, err := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
276		if err != nil {
277			return "", "", "", fmt.Errorf("read origin remote: %w", err)
278		}
279		info, err := gitremote.ParseURL(raw)
280		if err != nil {
281			return "", "", "", fmt.Errorf("parse origin remote: %w", err)
282		}
283		if info.Forge != mirrorUseForge {
284			return "", "", "", errors.New("interactive configure currently requires a GitHub origin remote")
285		}
286		clean, err := cleanRemoteURLForReport(raw)
287		if err != nil {
288			return "", "", "", err
289		}
290		return strings.ToLower(info.Owner), strings.ToLower(info.Repo), clean, nil
291	}
