515	type configureUpstreamField struct {
516		*huh.Select[string]
517	
518		value         *string
519		committed     string
520		highlighted   string
521		refresh       func()
522		layoutChanged func()
523		window        tea.WindowSizeMsg
524		focused       bool
525	}
526	
527	func (field *configureUpstreamField) Focus() tea.Cmd {
528		field.focused = true
529		return tea.Batch(field.Select.Focus(), configureRefreshFocus())
530	}
531	
532	func (field *configureUpstreamField) Blur() tea.Cmd {
533		field.focused = false
534		return field.Select.Blur()
535	}
