954	func runConfigureAgentManagement(cmd *cobra.Command, opts EnableOptions) error {
955		cmd.SilenceUsage = true
956		ctx := cmd.Context()
957		outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
958		repoRoot, err := paths.WorktreeRoot(ctx)
959		if err != nil {
960			return errors.New("not a git repository")
961		}
962		if !interactive.CanPromptInteractively() {
963			return runManageAgents(ctx, outW, opts, nil)
964		}
965	
966		initialChanges, err := configureGitChanges(ctx, repoRoot)
967		if err != nil {
968			return err
969		}
970		branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
971		if branchErr != nil {
972			branch = ""
973		}
974		owner, repo, _, identityErr := configureRepoIdentity(ctx)
975		forgeRemote := ""
976		if identityErr == nil {
977			remotes, remotesErr := listGitRemotes(ctx, repoRoot)
978			if remotesErr != nil {
979				return remotesErr
980			}
981			forgeRemote, err = configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, "")
982			if err != nil {
983				return err
984			}
985		}
986		protected := false
987		if branch != "" && identityErr == nil {
988			if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
989				protected = detected
990			}
991		}
992		pushSafe := branch != "" && forgeRemote != "" && len(initialChanges) == 0 &&
993			configureBranchMatchesRemoteHead(ctx, repoRoot, forgeRemote, "refs/heads/"+branch)
994		installedNames := GetAgentsWithHooksInstalled(ctx)
995		selectedNames, saveChoice, changed, err := promptConfigureAgentsAndSave(ctx, errW, installedNames, branch, protected, pushSafe)
996		if err != nil {
997			return err
998		}
999		if saveChoice == configureSaveCancel {
1000			fmt.Fprintln(outW, "Agent configuration cancelled.")
1001			return nil
1002		}
1003		if !changed {
1004			fmt.Fprintln(outW, "No agent configuration changes.")
1005			return nil
1006		}
1007	
1008		beforeApply, err := configureGitChanges(ctx, repoRoot)
1009		if err != nil {
1010			return err
1011		}
1012		if (saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch) &&
1013			(len(beforeApply) != 0 || !configureBranchMatchesRemoteHead(ctx, repoRoot, forgeRemote, "refs/heads/"+branch)) {
1014			saveChoice = configureSaveLocal
1015		}
1016		if err := applyAgentChanges(ctx, outW, selectedNames, installedNames, opts); err != nil {
1017			return err
1018		}
1019		if saveChoice != configureSaveDirect && saveChoice != configureSaveNewBranch {
1020			return nil
1021		}
1022		afterApply, err := configureGitChanges(ctx, repoRoot)
1023		if err != nil {
1024			return err
1025		}
1026		generated := newConfigureChanges(beforeApply, afterApply)
1027		return configureSaveAndPush(cmd, repoRoot, owner, repo, beforeApply, generated, branch, protected, saveChoice, forgeRemote, time.Now)
1028	}
