1158	func configureFormTheme() huh.Theme {
1159		return huh.ThemeFunc(func(isDark bool) *huh.Styles {
1160			theme := uiform.Theme().Theme(isDark)
1161			success := lipgloss.Color(palette.Success)
1162			muted := lipgloss.Color(palette.Muted)
1163	
1164			// Radio and checkbox lists use the same active-row indicator. Selection
1165			// remains green and independent from the orange `>` cursor.
1166			theme.FieldSeparator = lipgloss.NewStyle().SetString("")
1167			theme.Focused.Base = lipgloss.NewStyle()
1168			theme.Blurred.Base = lipgloss.NewStyle()
1169			theme.Focused.SelectSelector = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)).SetString("> ")
1170			theme.Blurred.SelectSelector = lipgloss.NewStyle().SetString("  ")
1171			theme.Focused.MultiSelectSelector = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)).SetString("> ")
1172			theme.Blurred.MultiSelectSelector = lipgloss.NewStyle().SetString("  ")
1173			theme.Focused.SelectedPrefix = lipgloss.NewStyle().Foreground(success).SetString("◼ ")
1174			theme.Blurred.SelectedPrefix = lipgloss.NewStyle().Foreground(success).SetString("◼ ")
1175			theme.Focused.UnselectedPrefix = lipgloss.NewStyle().Foreground(muted).SetString("◻ ")
1176			theme.Blurred.UnselectedPrefix = lipgloss.NewStyle().Foreground(muted).SetString("◻ ")
1177			theme.Focused.SelectedOption = theme.Focused.SelectedOption.UnsetForeground()
1178			theme.Blurred.SelectedOption = theme.Blurred.SelectedOption.UnsetForeground()
1179			// Enabled options keep normal text contrast whether selected or not.
1180			// Muting the empty checkbox is sufficient; muting the label itself can
1181			// incorrectly communicate that the option is disabled.
1182			theme.Focused.UnselectedOption = theme.Focused.UnselectedOption.UnsetForeground()
1183			theme.Blurred.UnselectedOption = theme.Blurred.UnselectedOption.UnsetForeground()
1184			return theme
1185		})
1186	}
