1222	func configurePlacementOrder(placements []coreapi.ResolvedPlacement, currentHost, jurisdiction string) []coreapi.ResolvedPlacement {
1223		ordered := append([]coreapi.ResolvedPlacement(nil), placements...)
1224		sort.SliceStable(ordered, func(i, j int) bool {
1225			iCurrent := strings.EqualFold(ordered[i].ClusterHost, currentHost)
1226			jCurrent := strings.EqualFold(ordered[j].ClusterHost, currentHost)
1227			if iCurrent != jCurrent {
1228				return iCurrent
1229			}
1230			iHome := strings.EqualFold(ordered[i].Jurisdiction.Or(""), jurisdiction)
1231			jHome := strings.EqualFold(ordered[j].Jurisdiction.Or(""), jurisdiction)
1232			if currentHost == "" && iHome != jHome {
1233				return iHome
1234			}
1235			return configurePlacementLabel(ordered[i]) < configurePlacementLabel(ordered[j])
1236		})
