1240	func configurePlacementLabel(placement coreapi.ResolvedPlacement) string {
1241		if jurisdiction := strings.ToLower(strings.TrimSpace(placement.Jurisdiction.Or(""))); jurisdiction != "" {
1242			if name, ok := configureJurisdictionNames[jurisdiction]; ok {
1243				return name
1244			}
1245			return strings.ToUpper(jurisdiction)
1246		}
1247		if cell := strings.TrimSpace(placement.Cell.Or("")); cell != "" {
1248			return cell
1249		}
1250		return placement.ClusterHost
1251	}
1252	
1253	var configureJurisdictionNames = map[string]string{ //nolint:gochecknoglobals // immutable display-name lookup
1254		"au": "Australia",
1255		"eu": "European Union",
1256		"in": "India",
1257		"us": "United States",
