1262		if installed := GetAgentsWithHooksInstalled(ctx); len(installed) > 0 {
1263			for _, name := range installed {
1264				selected[name] = struct{}{}
1265			}
1266			return selected
1267		}
1268		for _, detected := range agent.DetectAll(ctx) {
