1276	func configureUseMirror(ctx context.Context, outW, errW io.Writer, repoRoot, owner, repo string, chosen coreapi.ResolvedPlacement) (string, error) {
1277		remotes, err := listGitRemotes(ctx, repoRoot)
1278		if err != nil {
1279			return "", err
1280		}
1281		current := ""
1282		if remotes[defaultMirrorRemote] {
1283			current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1284			if err != nil {
1285				return "", fmt.Errorf("read origin remote URL: %w", err)
1286			}
1287		}
1288	
1289		forgeRemote, err := configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, defaultMirrorRemote)
1290		if err != nil {
1291			return "", err
1292		}
1293		preserve := ""
1294		if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol != gitremote.ProtocolEntire {
1295			if forgeRemote == "" {
1296				preserve = availableConfigureRemoteName(remotes, defaultMirrorUpstreamRemote, mirrorCloneProviderGitHub)
1297				forgeRemote = preserve
1298			}
1299		}
1300		if forgeRemote == "" {
1301			forgeRemote = availableConfigureRemoteName(remotes, mirrorCloneProviderGitHub)
1302			forgeURL := configureGitHubForgeURL(ctx, owner, repo)
1303			if _, err := gitRunner(ctx, repoRoot, "remote", "add", forgeRemote, forgeURL); err != nil {
1304				return "", fmt.Errorf("add GitHub push remote %q: %w", forgeRemote, err)
1305			}
1306			remotes[forgeRemote] = true
1307			fmt.Fprintf(outW, "✓ Added GitHub push remote %q\n  %s\n", forgeRemote, forgeURL)
1308		}
1309	
1310		mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
1311		plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
1312		if err := applyMirrorRemotePlan(ctx, repoRoot, plan); err != nil {
1313			return "", err
1314		}
1315		if err := configureRetargetCurrentBranch(ctx, repoRoot, forgeRemote); err != nil {
1316			return "", err
1317		}
1318		// Report the replaced URL and where it remains reachable. The returned
1319		// forgeRemote is deliberately separate from the mirror fetch remote: config
1320		// commits must land on GitHub, never in the one-way Entire mirror.
1321		reportMirrorRemotePlan(outW, errW, plan)
1322		return forgeRemote, nil
1323	}
