1325	var configureGitHubProtocol = func(ctx context.Context) string { //nolint:gochecknoglobals // test seam for the user's gh protocol preference
1326		out, err := exec.CommandContext(ctx, "gh", "config", "get", "git_protocol", "--host", "github.com").Output()
1327		if err != nil {
1328			return "https"
1329		}
1330		protocol := strings.ToLower(strings.TrimSpace(string(out)))
1331		if protocol == configureGitProtocolSSH {
1332			return protocol
1333		}
1334		return "https"
